def control(obs):
    import math
    look = -23
    steer = 0.0
    speed = -0.45
    hitch = obs.get('hitch_deg', 0.0)
    steer += max(-14.0, min(14.0, 0.9 * hitch))
    cam = obs.get('views', {}).get('camera')
    if cam:
        pts = []
        for b, d in cam.get('walls', []):
            r = math.radians(b)
            x = cam['origin'][0] + d * math.cos(r)
            y = cam['origin'][1] + d * math.sin(r)
            if x < -1.5:
                pts.append((x, y))
        left = [p for p in pts if p[1] > 0.3]
        right = [p for p in pts if p[1] < -0.3]
        centers = []
        for x, y in left:
            if right:
                q = min(right, key=lambda p: abs(p[0] - x))
                if abs(q[0] - x) < 3.0:
                    centers.append(((x + q[0]) * 0.5, (y + q[1]) * 0.5))
        if centers:
            cy = sum(p[1] for p in centers) / len(centers)
            steer += max(-8.0, min(8.0, -2.2 * cy))
    steer = max(-22.0, min(22.0, steer))
    if abs(hitch) > 28:
        steer = 18.0 if hitch > 0 else -18.0
    return (steer, speed, look)

