def clamp(x,a,b): return max(a,min(b,x))
def control(obs):
    h=obs.get('hitch_deg',0.0)
    v=(obs.get('views') or {}).get('direct') or {}
    ox,oy=v.get('origin',[0.1,0.0])
    left=[]; right=[]
    for b,d in v.get('walls',[]):
        a=math.radians(b); x=ox+d*math.cos(a); y=oy+d*math.sin(a)
        if -4.0 < x < -0.7:
            if y>0.05: left.append(y)
            elif y < -0.05: right.append(-y)
    if left and right:
        visual=clamp(2.0*(min(right)-min(left)),-5.0,5.0)
    elif left:
        visual=3.0
    elif right:
        visual=-3.0
    else:
        visual=0.0
    steer=clamp(visual-1.0*h,-8.0,8.0)
    return (steer,-0.10,165.0)

