def control(obs):
    h = obs.get('hitch_deg', 0.0)
    if obs.get('status') == 'PINNED':
        return (-8.0, 0.8, -41.0)
    if not globals().get('_recovered', False):
        globals()['_recover_t'] = globals().get('_recover_t', 0.0) + obs.get('dt', 0.1)
        if globals()['_recover_t'] < 5.0:
            return (-8.0, 0.8, -41.0)
        globals()['_recovered'] = True
    steer = max(-16.0, min(16.0, 1.5*h))
    return (steer, -0.45, -41.0)

