def control(obs):
    h = float(obs.get('hitch_deg', 0.0))
    if not globals().get('_straightened', False):
        globals()['_fwd_s'] = globals().get('_fwd_s', 0.0) + float(obs.get('dt', 0.1))
        if globals()['_fwd_s'] < 3.0:
            return (0.0, 0.35, 0.0)
        globals()['_straightened'] = True
    prev = globals().get('_h_prev', h)
    dt = max(float(obs.get('dt', 0.1)), 0.1)
    dh = (h - prev) / dt
    globals()['_h_prev'] = h
    steer = max(-24.0, min(24.0, 1.5*h - 0.08*dh))
    return (steer, -0.28, -41.0)

